public static bool IsValid(string s)
{
    var stack = new Stack<char>();
    foreach (var c in s)
    {
        switch (c)
        {
            case '(' or '[' or '{': stack.Push(c); break;
            case ')' when stack.Count == 0 || stack.Pop() != '(': return false;
            case ']' when stack.Count == 0 || stack.Pop() != '[': return false;
            case '}' when stack.Count == 0 || stack.Pop() != '{': return false;
        }
    }
    return stack.Count == 0;
}
