// G-Counter and PN-Counter
public sealed record GCounter(ImmutableDictionary<string, long> Counts)
{
    public static GCounter Empty => new(ImmutableDictionary<string, long>.Empty);
    public GCounter Increment(string replica, long by = 1) => new(Counts.SetItem(replica, Counts.GetValueOrDefault(replica) + by));
    public long Value => Counts.Values.Sum();
    public GCounter Merge(GCounter other) => new(Counts.Keys.Union(other.Counts.Keys)
        .ToImmutableDictionary(k => k, k => Math.Max(Counts.GetValueOrDefault(k), other.Counts.GetValueOrDefault(k))));
}

// OR-Set: each add gets a unique tag; remove deletes only the tags it has observed (add wins over concurrent remove)
public sealed record OrSet<T>(ImmutableHashSet<(T Item, Guid Tag)> Adds, ImmutableHashSet<Guid> Removed) where T : notnull
{
    public OrSet<T> Add(T item) => this with { Adds = Adds.Add((item, Guid.NewGuid())) };
    public OrSet<T> Remove(T item) => this with { Removed = Removed.Union(Adds.Where(a => a.Item.Equals(item)).Select(a => a.Tag)) };
    public IEnumerable<T> Items => Adds.Where(a => !Removed.Contains(a.Tag)).Select(a => a.Item).Distinct();
    public OrSet<T> Merge(OrSet<T> o) => new(Adds.Union(o.Adds), Removed.Union(o.Removed));
}
